import{_ as o,l,o as e,c as i,v as r,p as h,x as n,d as s,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"并行查询与 exchange","description":"","frontmatter":{"title":"并行查询与 exchange","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/parallel-exchange.md","filePath":"cs/parallel-exchange.md","lastUpdated":1789023840000}'),p={name:"cs/parallel-exchange.md"};function f(E,a,g,x,u,_){const t=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="并行查询与-exchange" tabindex="-1">并行查询与 exchange <a class="header-anchor" href="#并行查询与-exchange" aria-label="Permalink to &quot;并行查询与 exchange&quot;">​</a></h1><div class="epigraph"><p>exchange 把 Volcano 树切成多个数据流：广播、重分区、收集。并行度是计划上的标签，不是另一种 SQL。</p><footer>—— 据 Graefe Volcano 并行；DeWitt and Gray 并行数据库；Selinger 之后的物理标签</footer></div><p><a href="/cs/grace-hash-join">上一课</a>在单机用文件分区。本课不递归划分。缺口是多核与多节点：同一逻辑算子跑 \\(D\\) 份，数据必须按连接键对齐或广播。exchange（交换算子）实现 Volcano 的 <code>next</code>，底下是队列、网络或共享内存。主干分片直觉点到水平切；进阶钉执行器里的切流。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流水并行：不同算子叠在不同核（有限）。划分并行：同一扫描切成 range/hash/round-robin 多工人。连接：若两边都按连接键 hash 重分区（shuffle join），则工人 \\(i\\) 只连自己的键范围，正确性同 Grace。广播连接：小侧复制到所有工人，大侧划分扫——避免大 shuffle。</p><p>缺口是 <strong>exchange 的次序与代价</strong>：网络比内存哈希贵，优化器要把 shuffle 字节计入校准过的模型。倾斜使某一工人收到大部分键，并行名存实亡。</p><p><span class="marginnote">Graefe 把 exchange 插进迭代器树。DeWitt and Gray，《Communications of the ACM》并行数据库。分布式后课 shuffle 与本课同构，只是网络更宽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计划节点标 DOP。扫描：按页或按范围并行。exchange 类型：gather（收向协调器）、repartition（按键）、broadcast、round-robin。资源：工人数 ≤ 核数或槽位；超订会抖。</p><p>合并有序流：并行排序后 merge exchange 保序，服务归并连接。破坏序的 exchange 会逼上层再排。</p>',10)),(e(),h(d,null,{default:n(()=>[c(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCAN%5B%22%E5%B9%B6%E8%A1%8C%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20EX1%5B%22repartition%20%E6%8C%89%E8%BF%9E%E6%8E%A5%E9%94%AE%22%5D%0A%20%20BCAST%5B%22%E5%B0%8F%E8%A1%A8%E5%B9%BF%E6%92%AD%22%5D%20--%3E%20HJ%5B%22%E5%B7%A5%E4%BA%BA%E6%9C%AC%E5%9C%B0%E5%93%88%E5%B8%8C%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20EX1%20--%3E%20HJ%0A%20%20HJ%20--%3E%20G%5B%22gather%20%E5%88%B0%E6%A0%B9%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>事务与快照：所有工人读同一快照（MVCC）或同一锁协议视图。取消：协调器 close 所有 exchange。死锁：工人之间若再拿锁，等待图跨线程——事务进阶课。本课假设扫描与哈希工作集已定。</p><p>代价：启动工人的固定税使短查询并行变慢。优化器应对小基数关并行——回归可表现为「自动 DOP 开太大」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲列存延迟物化——下一课。也不把两阶段提交当 exchange。存算分离后课的 shuffle 落在对象存储上，接口仍是这三种交换。</p><p>后课默认：并行计划用 exchange 显式切流；广播 vs shuffle 由大小估计决定。延迟物化决定工人之间传列还是传 RID。</p><p>没有 exchange 的「并行」只是算子内 SIMD，不是划分并行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>exchange 提供 gather、repartition、broadcast，对齐 Grace 正确性。</li><li>倾斜与启动税限制 DOP；短查询常串行。</li><li>延迟物化下一课：尽量晚读列，减少 shuffle 宽度。</li><li>出处：Graefe；DeWitt and Gray；Ramakrishnan and Gehrke。</li></ul>',9))])}const B=o(p,[["render",f]]);export{A as __pageData,B as default};
